WITH cleaned AS (SELECT *, QUARTER(start_date) AS start_date_quarter FROM subscriptions WHERE end_date BETWEEN '2024-02-10' AND '2025-05-07') SELECT customer_id, DATE_TRUNC('MONTH', end_date) AS activity_month, CASE WHEN monthly_fee >= 222 THEN 'HIGH' ELSE 'LOW' END AS monthly_fee_tier, APPROX_PERCENTILE(monthly_fee, ARRAY(0.25, 0.5, 0.75)) AS monthly_fee_quartiles, PERCENTILE_APPROX(start_date_quarter, 0.9) AS start_date_quarter_p90, PERCENTILE_APPROX(start_date_quarter, 0.5) AS start_date_quarter_p50, COUNT_IF(status = 'EXPIRED') AS expired_events, AVG(monthly_fee) FILTER (WHERE status = 'PAUSED') AS paused_avg_monthly_fee, COUNT(CASE WHEN plan = 'basic' THEN 1 END) AS basic_count FROM cleaned GROUP BY customer_id, DATE_TRUNC('MONTH', end_date), CASE WHEN monthly_fee >= 222 THEN 'HIGH' ELSE 'LOW' END;
